const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization;
if (!authHeader || typeof authHeader !== 'string') { throw new Error('Unauthorized'); }
const parts = authHeader.split(' ');
if (parts.length < 2 || !parts[1]) { throw new Error('Unauthorized'); }
const tokenParts = parts[1].split('.');
if (tokenParts.length < 2) { throw new Error('Unauthorized'); }
const base64 = tokenParts[1].replace(/-/g, '+').replace(/_/g, '/');
const payload = JSON.parse(Buffer.from(base64, 'base64').toString('utf8'));
const body = $input.first().json.body || {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const question = (body.question || '').toString().trim();
let validationError = null;
if (!question) validationError = 'من فضلك اكتب سؤالك';
else if (question.length > 1000) validationError = 'السؤال طويل جدًا (الحد الأقصى 1000 حرف)';

// كل القيم بتتحوّل لنص ('' = مفيش) عشان الاستعلامات تستخدم NULLIF(...)
const bookId = UUID_RE.test(String(body.book_id || '')) ? String(body.book_id) : '';
const studentId = UUID_RE.test(String(body.student_id || '')) ? String(body.student_id) : '';
const pageNum = parseInt(body.page, 10);
const page = Number.isInteger(pageNum) && pageNum > 0 && pageNum < 100000 ? String(pageNum) : '';

// سياق المحادثة (آخر 8 رسائل) لأسئلة المتابعة
const history = (Array.isArray(body.history) ? body.history : [])
  .filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.text === 'string' && m.text.trim())
  .slice(-8)
  .map(m => ({ role: m.role, text: m.text.trim().slice(0, 1200) }));
const lastUser = history.slice().reverse().find(m => m.role === 'user');
// سؤال قصير (متابعة) بيتضاف له سؤال المعلم السابق عشان البحث بالمعنى يلاقي المقاطع الصح
const retrievalText = (question.length < 60 && lastUser) ? (lastUser.text.slice(0, 300) + '\n' + question) : question;

return {
  teacherId: payload.sub,
  studentId,
  bookId,
  bookScoped: !!bookId,
  page,
  question,
  history,
  retrievalText,
  isValid: validationError === null,
  validationError,
  minIntervalSeconds: 5,
  dailyLimit: 40,
  topK: bookId ? 8 : 6,
  geminiModel: 'gemini-3.5-flash-lite',
  embeddingModel: 'gemini-embedding-001'
};

const cfg = $('Decode JWT & Config').item.json;
const raw = $input.first().json || {};
const values = raw.embedding && Array.isArray(raw.embedding.values) ? raw.embedding.values : null;
if (!values) {
  return { embedFailed: true, teacherId: cfg.teacherId };
}
return {
  teacherId: cfg.teacherId,
  studentId: cfg.studentId,
  bookId: cfg.bookId,
  page: cfg.page,
  question: cfg.question,
  topK: cfg.topK,
  embeddingLiteral: '[' + values.join(',') + ']'
};

