parameters.jsCode:
const prev = $('Build Answer Prompt').item.json;
const cfg = $('Decode JWT & Config').item.json;
const raw = $input.first().json || {};

if (raw.error) {
  const s = JSON.stringify(raw.error).slice(0, 300);
  if (/429|RESOURCE_EXHAUSTED|quota|rate.?limit|overloaded|503|UNAVAILABLE/i.test(s)) {
    return { json: { success: false, code: 'BUSY', message: 'خدمة الذكاء الاصطناعي مشغولة الآن، من فضلك أعد المحاولة بعد لحظات.' } };
  }
  return { json: { success: false, code: 'AI_ERROR', message: 'تعذّر توليد الإجابة، من فضلك حاول مرة أخرى.' } };
}

const candidate = raw.candidates && raw.candidates[0];
const text = candidate && candidate.content && Array.isArray(candidate.content.parts)
  ? candidate.content.parts.map(p => p.text || '').join('') : '';
if (!text.trim()) {
  return { json: { success: false, code: 'AI_ERROR', message: 'تعذّر توليد إجابة مناسبة لهذا السؤال.' } };
}

const used = Number($('Reserve Daily Quota').item.json.request_count) || 0;
return {
  json: {
    success: true,
    answer: text.trim(),
    sources: prev.sources,
    remaining: Math.max(0, cfg.dailyLimit - used),
    truncated: candidate && candidate.finishReason === 'MAX_TOKENS'
  }
};

